package io.knowledgebrain.planning;
import java.time.*;import java.util.*;import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class ReminderDeliveryApiTest {
 ReminderDeliveryStore store;SpaceAuthorizationClient auth;ReminderDeliveryController api;UUID space,reminder,id,actor;
 @BeforeEach void init(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();reminder=ids.next();id=ids.next();actor=ids.next();store=mock(ReminderDeliveryStore.class);auth=mock(SpaceAuthorizationClient.class);when(auth.authorize(eq(space),any(),anyString(),eq("PRIVATE"),anyString())).thenReturn(actor);api=new ReminderDeliveryController(store,auth,"https://localhost:8443",new SimpleMeterRegistry());}
 MockHttpServletRequest r(String method,String body){var r=new MockHttpServletRequest(method,"/api/spaces/"+space+"/reminders/"+reminder+"/deliveries");r.setSecure(true);r.setContentType("application/json");r.setCookies(new Cookie("__Host-brain_guest","b".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.addHeader("Idempotency-Key","c".repeat(32));if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 @Test void strictExplicitArmingHasFreshWriteAuthorityAndOneBoundedVersion()throws Exception{for(String bad:List.of("{}","{\"reminderVersion\":1.0}","{\"reminderVersion\":9223372036854775808}","{\"reminderVersion\":1,\"reminderVersion\":2}","{\"reminderVersion\":1} {}","{\"reminderVersion\":1,\"actorId\":null}"))assertThrows(ResponseStatusException.class,()->api.arm(space.toString(),reminder.toString(),r("POST",bad)));var cross=r("POST","{\"reminderVersion\":1}");cross.removeHeader("Origin");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.arm(space.toString(),reminder.toString(),cross)).getStatusCode().value());verifyNoInteractions(store);verify(auth,atLeastOnce()).authorize(eq(space),any(),eq("SCHEDULE_WRITE"),eq("PRIVATE"),anyString());}
 @Test void cancellationUsesItsOwnStrongEtagAndReadHistoryRechecksAuthority(){var no=r("DELETE",null);assertEquals(428,assertThrows(ResponseStatusException.class,()->api.cancel(space.toString(),reminder.toString(),id.toString(),no)).getStatusCode().value());for(String tag:List.of("\"rm1\"","W/\"dp1\"","\"dp01\"","*")){var bad=r("DELETE",null);bad.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.cancel(space.toString(),reminder.toString(),id.toString(),bad));}api.history(space.toString(),reminder.toString(),id.toString(),r("GET",null));verify(auth).authorize(eq(space),any(),eq("SCHEDULE_READ"),eq("PRIVATE"),anyString());var dup=r("GET",null);dup.addParameter("limit","20","100");assertThrows(ResponseStatusException.class,()->api.list(space.toString(),reminder.toString(),dup));}
 @Test void canonicalDispatchExportRequiresDedicatedTlsCapabilityAndNoBrowserCookie(){var export=new ReminderDispatchExportController(store,"a".repeat(43));var r=new MockHttpServletRequest("GET","/internal/planning/dispatched-reminders");r.setSecure(true);assertEquals(401,assertThrows(ResponseStatusException.class,()->export.export(r)).getStatusCode().value());r.addHeader("Authorization","Bearer "+"a".repeat(43));r.addHeader("Cookie","anything");assertEquals(403,assertThrows(ResponseStatusException.class,()->export.export(r)).getStatusCode().value());verifyNoInteractions(store);}
}
